        self.users = {}

    def join(self, ownedChunks):
        i = 1
        while i in self.users:
            i += 1
        self.users[i] = set(ownedChunks)
        return i

    def leave(self, userID):
        del self.users[userID]

    def request(self, userID, chunkID):
        res = [u for u, c in self.users.items() if chunkID in c]
        res.sort()
