class FileSharing {
public:
    FileSharing(int m) {}

    int join(vector<int>& ownedChunks) {
        int id = 1;
        while (users.count(id)) id++;
        users[id] = unordered_set<int>(ownedChunks.begin(), ownedChunks.end());
        return id;
    }

    void leave(int userID) { users.erase(userID); }

    vector<int> request(int userID, int chunkID) {
        vector<int> res;
        for (auto& [u, c] : users)
            if (c.count(chunkID)) res.push_back(u);
        sort(res.begin(), res.end());
        return res;
    }
private:
    unordered_map<int, unordered_set<int>> users;
};

