class FileSharing {
    private Map<Integer, Set<Integer>> users = new HashMap<>();

    public FileSharing(int m) {}

    public int join(List<Integer> ownedChunks) {
        int id = 1;
        while (users.containsKey(id)) id++;
        users.put(id, new HashSet<>(ownedChunks));
        return id;
    }

    public void leave(int userID) { users.remove(userID); }

    public int[] request(int userID, int chunkID) {
        List<Integer> res = new ArrayList<>();
        for (Map.Entry<Integer, Set<Integer>> e : users.entrySet())
            if (e.getValue().contains(chunkID)) res.add(e.getKey());
        Collections.sort(res);
        int[] out = new int[res.size()];
        for (int i = 0; i < out.length; i++) out[i] = res.get(i);
        return out;
    }
}

