import heapq
from sortedcontainers import SortedList

class FileSharing:
    def __init__(self, m):
        self.heap = list(range(1, m + 1))
        heapq.heapify(self.heap)
        self.chunkOwners = defaultdict(SortedList)
        self.userChunks = {}

    def join(self, ownedChunks):
        uid = heapq.heappop(self.heap)
        self.userChunks[uid] = ownedChunks
        for c in ownedChunks:
            self.chunkOwners[c].add(uid)
        return uid

    def leave(self, userID):
        for c in self.userChunks.pop(userID):
            self.chunkOwners[c].remove(userID)
        heapq.heappush(self.heap, userID)

    def request(self, userID, chunkID):
        return list(self.chunkOwners[chunkID])

