class FileSharing {
public:
    FileSharing(int m) : m_(m), nextId_(1) {}

    int join(vector<int>& ownedChunks) {
        int uid;
        if (!free_.empty()) { uid = free_.top(); free_.pop(); }
        else uid = nextId_++;
        userChunks_[uid] = ownedChunks;
        for (int c : ownedChunks) {
            auto& s = owners_[c];
            s.insert(lower_bound(s.begin(), s.end(), uid), uid);
        }
        return uid;
    }

    void leave(int userID) {
        for (int c : userChunks_[userID]) {
            auto& v = owners_[c];
            v.erase(lower_bound(v.begin(), v.end(), userID));
        }
        userChunks_.erase(userID);
        free_.push(userID);
    }

    vector<int> request(int userID, int chunkID) {
        return owners_[chunkID];
    }
private:
    int m_, nextId_;
    priority_queue<int, vector<int>, greater<int>> free_;
    unordered_map<int, vector<int>> userChunks_;
    unordered_map<int, vector<int>> owners_;
};

