class FileSharing {
    private PriorityQueue<Integer> free = new PriorityQueue<>();
    private int nextId = 1;
    private Map<Integer, List<Integer>> userChunks = new HashMap<>();
    private Map<Integer, TreeSet<Integer>> owners = new HashMap<>();

    public FileSharing(int m) {}

    public int join(List<Integer> ownedChunks) {
        int uid = free.isEmpty() ? nextId++ : free.poll();
        userChunks.put(uid, ownedChunks);
        for (int c : ownedChunks)
            owners.computeIfAbsent(c, k -> new TreeSet<>()).add(uid);
        return uid;
    }

    public void leave(int userID) {
        for (int c : userChunks.remove(userID))
            owners.get(c).remove(userID);
        free.offer(userID);
    }

    public int[] request(int userID, int chunkID) {
        TreeSet<Integer> s = owners.get(chunkID);
        if (s == null) return new int[0];
        int[] res = new int[s.size()];
        int i = 0;
        for (int u : s) res[i++] = u;
        return res;
    }
}

