var FileSharing = function(m) {
    this.free = [];
    this.nextId = 1;
    this.userChunks = new Map();
    this.owners = new Map();
};

FileSharing.prototype.join = function(ownedChunks) {
    let uid;
    if (this.free.length) {
        this.free.sort((a, b) => a - b);
        uid = this.free.shift();
    } else uid = this.nextId++;
    this.userChunks.set(uid, ownedChunks);
    for (const c of ownedChunks) {
        if (!this.owners.has(c)) this.owners.set(c, []);
        const arr = this.owners.get(c);
        arr.splice(this.lowerBound(arr, uid), 0, uid);
    }
    return uid;
};

FileSharing.prototype.lowerBound = function(arr, x) {
    let lo = 0, hi = arr.length;
    while (lo < hi) {
        const mid = (lo + hi) >> 1;
        if (arr[mid] < x) lo = mid + 1; else hi = mid;
    }
    return lo;
};

FileSharing.prototype.leave = function(userID) {
    for (const c of this.userChunks.get(userID)) {
        const arr = this.owners.get(c);
        arr.splice(arr.indexOf(userID), 1);
    }
    this.userChunks.delete(userID);
    this.free.push(userID);
};

FileSharing.prototype.request = function(userID, chunkID) {
    return this.owners.get(chunkID) || [];
};
